insert into email_templates (key, name, description, is_active, subject_en, subject_ar, body_html_en, body_html_ar, variables) values
('beta_invite', 'Private Beta Invitation', 'One-off bilingual invite sent manually to waitlist signups inviting them into the private beta assessment.', true,
 'You''ve Been Selected to Test Etijahi · تم اختيارك لتجربة اتجاهي', 'You''ve Been Selected to Test Etijahi · تم اختيارك لتجربة اتجاهي',
 '<br><span style="display: none; font-size: 0px; line-height: 0; max-height: 0px; opacity: 0; overflow: hidden;">تم اختيارك ضمن المجموعة الأولى لتجربة اتجاهي · You''ve been selected for the private beta.</span>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background: rgb(235, 243, 255); margin: 0px; padding: 0px; text-size-adjust: 100%;">
  <tbody><tr>
    <td align="center" style="padding: 24px 10px; text-size-adjust: 100%;">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%; background: rgb(255, 255, 255); border-radius: 18px; overflow: hidden; box-shadow: rgba(0, 82, 204, 0.1) 0px 12px 40px; text-size-adjust: 100%;">

        <tbody><tr>
          <td bgcolor="#FFFFFF" style="background: rgb(255, 255, 255); padding: 38px 40px 30px; text-size-adjust: 100%;" align="center">
            <img src="https://erp.etijahcoaching.com/media/Etijahi/etijahi-logo-horizontal-single-icon.png" width="300" alt="Etijahi · إتجاهي" style="display: block; width: 300px; max-width: 78%; height: auto; margin: 0px auto 12px; border: 0px; outline: none; text-decoration: none;">
            <p style="margin: 0px; color: rgb(90, 106, 133);"><span style="font-family: Arial, Helvetica, sans-serif; font-size: 10px;">by Etijah Coaching &amp; Consulting</span> &nbsp;·&nbsp; <span style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 10px;">من اتجاه للإرشاد والاستشارات</span></p>
          </td>
        </tr>

        <tr>
          <td bgcolor="#0052CC" style="background: rgb(0, 82, 204); padding: 14px 40px; text-size-adjust: 100%;">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" dir="ltr" style="text-size-adjust: 100%;"><tbody><tr>
              <td width="50%" align="left" dir="ltr" style="font-family: Arial, Helvetica, sans-serif; font-size: 13px; font-weight: bold; letter-spacing: 1.5px; text-transform: uppercase; color: rgb(255, 255, 255); padding-right: 16px; text-size-adjust: 100%;">Private beta · Invitation</td>
              <td width="50%" align="right" dir="rtl" style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 15px; font-weight: bold; color: rgb(255, 255, 255); text-size-adjust: 100%;">دعوة خاصة للنسخة التجريبية</td>
            </tr></tbody></table>
          </td>
        </tr>
        <tr><td style="height: 4px; background: rgb(0, 201, 167); font-size: 0px; line-height: 0; text-size-adjust: 100%;">&nbsp;</td></tr>

        <tr>
          <td dir="rtl" align="right" style="padding: 34px 40px 0px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; text-size-adjust: 100%;">
            <p style="margin: 0px 0px 22px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 30px; line-height: 1.5; font-weight: bold; color: rgb(0, 82, 204);">تم اختيارك لتجربة اتجاهي</p>
            <p style="margin: 0px 0px 16px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">عزيزي/عزيزتي {{first_name}}،</p>
            <p style="margin: 0px 0px 16px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">يسعدنا إبلاغك بأنه تم اختيارك ضمن المجموعة الأولى لتجربة <strong style="color: rgb(0, 82, 204);">اتجاهي</strong> قبل الإطلاق العام.</p>
            <p style="margin: 0px 0px 22px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">اخترنا مجموعة محدودة لهذه المرحلة لأن <strong style="color: rgb(0, 82, 204);">رأيك وتجربتك معنا جزء أساسي من تطوير اتجاهي</strong>. ملاحظاتك ستساعدنا نفهم تجربتك بشكل أفضل، ونطوّر الأداة بناءً على احتياجات المستخدمين قبل إطلاقها للجميع.</p>
          </td>
        </tr>

        <tr><td dir="rtl" style="padding: 0px 40px 8px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td align="center" bgcolor="#EBF3FF" style="background: rgb(235, 243, 255); border: 1px solid rgb(207, 224, 251); border-radius: 14px; padding: 28px 26px; text-size-adjust: 100%;">
              <p style="margin: 0px 0px 6px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 13px; font-weight: bold; letter-spacing: 0.5px; color: rgb(0, 82, 204);">رابط الدخول الخاص بك</p>
              <p dir="ltr" style="margin: 0px 0px 20px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.7; color: rgb(90, 106, 133); word-break: break-all;"><a href="https://myetijahi.com/en/assessment" style="color: rgb(0, 82, 204); text-decoration: underline; font-weight: bold;">myetijahi.com/en/assessment</a></p>
              <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width: auto; margin: 0px auto; text-size-adjust: 100%;"><tbody><tr>
                <td align="center" bgcolor="#00C9A7" style="border-radius: 40px; text-size-adjust: 100%;">
                  <a href="https://myetijahi.com/en/assessment" style="display: inline-block; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 17px; font-weight: bold; color: rgb(255, 255, 255); text-decoration: none; padding: 17px 46px; border-radius: 40px;">‏ابدأ تجربة اتجاهي&nbsp;←</a>
                </td>
              </tr></tbody></table>
              <p style="margin: 18px 0px 0px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 14px; line-height: 1.8; color: rgb(45, 45, 45);">يستغرق التقييم حوالي <strong style="color: rgb(0, 82, 204);">15 دقيقة</strong>، وننصحك بالإجابة بكل صدق، لأن دقة النتائج تعتمد على إجاباتك.</p>
            </td>
          </tr></tbody></table>
        </td></tr>

        <tr>
          <td dir="rtl" align="right" style="padding: 22px 40px 0px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; text-size-adjust: 100%;">
            <p style="margin: 0px 0px 22px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">بعد إكمال التقييم، سيظهر <strong style="color: rgb(0, 82, 204);">تقريرك مباشرة</strong>، وستجد <strong style="color: rgb(0, 82, 204);">استمارة الملاحظات في نهاية التقرير</strong>. كما سنرسل لك رابط الاستمارة مباشرة بعد إكمال التقييم.</p>
          </td>
        </tr>

        <tr><td dir="rtl" style="padding: 0px 40px 22px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td dir="rtl" align="right" style="background: rgb(255, 255, 255); border: 2px solid rgb(0, 201, 167); border-radius: 14px; padding: 22px 24px; text-size-adjust: 100%;">
              <p style="margin: 0px 0px 10px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 19px; font-weight: bold; color: rgb(0, 82, 204);">رأيك يهمنا</p>
              <p style="margin: 0px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);"><strong>مهم جدًا: نرجو منك تعبئة استمارة الملاحظات.</strong> هذه المرحلة التجريبية تعتمد بشكل كبير على ملاحظاتك، وكل رأي تقدمه يساعدنا في تحسين اتجاهي وتطوير التجربة قبل الإطلاق.</p>
            </td>
          </tr></tbody></table>
        </td></tr>

        <tr><td dir="rtl" align="right" style="padding: 0px 40px 28px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; text-size-adjust: 100%;">
          <p style="margin: 0px 0px 16px; font-size: 14px; line-height: 1.9; color: rgb(90, 106, 133);">متوفر بالعربية والإنجليزية. وإذا واجهت أي مشكلة، يكفي الرد على هذه الرسالة.</p>
          <p style="margin: 0px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">مع خالص التقدير،<br><strong>فريق اتجاه للإرشاد والاستشارات</strong></p>
        </td></tr>

        <tr><td style="padding: 6px 40px 28px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td width="44%" style="border-top: 1px solid rgb(220, 231, 251); font-size: 0px; line-height: 0; text-size-adjust: 100%;">&nbsp;</td>
            <td width="12%" align="center" style="font-size: 0px; line-height: 0; text-size-adjust: 100%;"><span style="display: inline-block; width: 9px; height: 9px; background: rgb(0, 201, 167); border-radius: 50%;">&nbsp;</span></td>
            <td width="44%" style="border-top: 1px solid rgb(220, 231, 251); font-size: 0px; line-height: 0; text-size-adjust: 100%;">&nbsp;</td>
          </tr></tbody></table>
        </td></tr>

        <tr>
          <td dir="ltr" align="left" style="padding: 0px 40px; font-family: Arial, Helvetica, sans-serif; text-size-adjust: 100%;">
            <p style="margin: 0px 0px 22px; font-family: Arial, Helvetica, sans-serif; font-size: 30px; line-height: 1.35; font-weight: bold; color: rgb(0, 82, 204);">You''ve Been Selected to Test Etijahi</p>
            <p style="margin: 0px 0px 16px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">Dear {{first_name}},</p>
            <p style="margin: 0px 0px 16px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">We''re pleased to let you know that you''ve been selected as part of the first group to <strong style="color: rgb(0, 82, 204);">test Etijahi</strong> ahead of its public launch.</p>
            <p style="margin: 0px 0px 22px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">We''ve kept this group intentionally small because <strong style="color: rgb(0, 82, 204);">your experience and feedback are an important part of building Etijahi</strong>. What you share with us will help us understand what works, what needs improvement, and how we can make the experience better before we open it to everyone.</p>
          </td>
        </tr>

        <tr><td dir="ltr" style="padding: 0px 40px 8px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td align="center" bgcolor="#EBF3FF" style="background: rgb(235, 243, 255); border: 1px solid rgb(207, 224, 251); border-radius: 14px; padding: 28px 26px; text-size-adjust: 100%;">
              <p style="margin: 0px 0px 6px; font-family: Arial, Helvetica, sans-serif; font-size: 12px; font-weight: bold; letter-spacing: 1.2px; text-transform: uppercase; color: rgb(0, 82, 204);">Your access link</p>
              <p style="margin: 0px 0px 20px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.7; color: rgb(90, 106, 133); word-break: break-all;"><a href="https://myetijahi.com/en/assessment" style="color: rgb(0, 82, 204); text-decoration: underline; font-weight: bold;">myetijahi.com/en/assessment</a></p>
              <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width: auto; margin: 0px auto; text-size-adjust: 100%;"><tbody><tr>
                <td align="center" bgcolor="#00C9A7" style="border-radius: 40px; text-size-adjust: 100%;">
                  <a href="https://myetijahi.com/en/assessment" style="display: inline-block; font-family: Arial, Helvetica, sans-serif; font-size: 17px; font-weight: bold; color: rgb(255, 255, 255); text-decoration: none; padding: 17px 44px; border-radius: 40px;">Start Your Etijahi Experience &nbsp;→</a>
                </td>
              </tr></tbody></table>
              <p style="margin: 18px 0px 0px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.8; color: rgb(45, 45, 45);">The assessment takes about <strong style="color: rgb(0, 82, 204);">15 minutes</strong>. We encourage you to answer honestly, as the quality of your results depends on your answers.</p>
            </td>
          </tr></tbody></table>
        </td></tr>

        <tr>
          <td dir="ltr" align="left" style="padding: 22px 40px 0px; font-family: Arial, Helvetica, sans-serif; text-size-adjust: 100%;">
            <p style="margin: 0px 0px 22px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">Once you complete the assessment, <strong style="color: rgb(0, 82, 204);">your report will appear immediately</strong>, with the <strong style="color: rgb(0, 82, 204);">feedback form at the end of the report</strong>. You''ll also receive a link to the feedback form immediately after completing the assessment.</p>
          </td>
        </tr>

        <tr><td dir="ltr" style="padding: 0px 40px 22px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td style="background: rgb(255, 255, 255); border: 2px solid rgb(0, 201, 167); border-radius: 14px; padding: 22px 24px; text-size-adjust: 100%;">
              <p style="margin: 0px 0px 10px; font-family: Arial, Helvetica, sans-serif; font-size: 19px; font-weight: bold; color: rgb(0, 82, 204);">Your Feedback Matters</p>
              <p style="margin: 0px; font-family: Arial, Helvetica, sans-serif; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);"><strong>Your feedback is especially important. Please make sure to complete the form.</strong> Your input at this stage will directly help us improve Etijahi and shape the experience before its wider launch.</p>
            </td>
          </tr></tbody></table>
        </td></tr>

        <tr><td dir="ltr" align="left" style="padding: 0px 40px 28px; font-family: Arial, Helvetica, sans-serif; text-size-adjust: 100%;">
          <p style="margin: 0px 0px 16px; font-size: 14px; line-height: 1.9; color: rgb(90, 106, 133);">Available in Arabic and English. If you experience any issues, simply reply to this email.</p>
          <p style="margin: 0px; font-size: 15px; line-height: 1.9; color: rgb(45, 45, 45);">With regards,<br><strong>Etijah Coaching &amp; Consulting Team</strong></p>
        </td></tr>

        <tr><td style="padding: 0px 40px 30px; text-size-adjust: 100%;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="text-size-adjust: 100%;"><tbody><tr>
            <td style="background: rgb(245, 249, 255); border-top: 3px solid rgb(0, 82, 204); border-radius: 14px; padding: 24px 24px 18px; text-size-adjust: 100%;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" dir="ltr" style="text-size-adjust: 100%;"><tbody><tr>
                <td width="50%" align="left" dir="ltr" style="font-family: Arial, Helvetica, sans-serif; font-size: 15px; font-weight: bold; color: rgb(0, 82, 204); padding-bottom: 6px; padding-right: 16px; text-size-adjust: 100%;">Need help?</td>
                <td width="50%" align="right" dir="rtl" style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 15px; font-weight: bold; color: rgb(0, 82, 204); padding-bottom: 6px; text-size-adjust: 100%;">هل تحتاج مساعدة؟</td>
              </tr><tr>
                <td width="50%" align="left" dir="ltr" style="font-family: Arial, Helvetica, sans-serif; font-size: 13px; line-height: 1.9; color: rgb(90, 106, 133); padding-bottom: 16px; padding-right: 16px; text-size-adjust: 100%;">For any question or technical issue: reply to this email, or reach us on WhatsApp or by phone.</td>
                <td width="50%" align="right" dir="rtl" style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 13px; line-height: 1.9; color: rgb(90, 106, 133); padding-bottom: 16px; text-size-adjust: 100%;">لأي سؤال أو مشكلة تقنية: يكفي الرد على هذه الرسالة، أو تواصل معنا عبر واتساب أو الهاتف.</td>
              </tr></tbody></table>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" dir="ltr" style="text-size-adjust: 100%;"><tbody><tr>
                <td width="50%" align="center" valign="top" style="padding: 0px 8px 0px 0px; text-size-adjust: 100%;">
                  <p style="margin: 0px 0px 4px; font-family: Arial, Helvetica, sans-serif; font-size: 11px; font-weight: bold; letter-spacing: 1px; text-transform: uppercase; color: rgb(90, 106, 133);">Saudi Arabia &nbsp;·&nbsp; <span style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; letter-spacing: 0px;">السعودية</span></p>
                  <p style="margin: 0px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 2.1;"><a dir="ltr" href="https://wa.me/966550770711" style="color: rgb(0, 82, 204); text-decoration: none; font-weight: bold; white-space: nowrap;"><img src="https://erp.etijahcoaching.com/media/Etijahi/etijahi-icon-whatsapp.png" width="16" height="16" alt="WhatsApp" style="width: 16px; height: 16px; vertical-align: middle; margin: 0px 6px 3px 0px; border: 0px; outline: none; text-decoration: none;">+966 55 077 0711</a></p>
                </td>
                <td width="50%" align="center" valign="top" style="padding: 0px 0px 0px 8px; text-size-adjust: 100%;">
                  <p style="margin: 0px 0px 4px; font-family: Arial, Helvetica, sans-serif; font-size: 11px; font-weight: bold; letter-spacing: 1px; text-transform: uppercase; color: rgb(90, 106, 133);">Bahrain &nbsp;·&nbsp; <span style="font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; letter-spacing: 0px;">البحرين</span></p>
                  <p style="margin: 0px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 2.1;"><a dir="ltr" href="https://wa.me/97333462820" style="color: rgb(0, 82, 204); text-decoration: none; font-weight: bold; white-space: nowrap;"><img src="https://erp.etijahcoaching.com/media/Etijahi/etijahi-icon-whatsapp.png" width="16" height="16" alt="WhatsApp" style="width: 16px; height: 16px; vertical-align: middle; margin: 0px 6px 3px 0px; border: 0px; outline: none; text-decoration: none;">+973 3346 2820</a></p>
                </td>
              </tr></tbody></table>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top: 16px; text-size-adjust: 100%;"><tbody><tr>
                <td align="center" style="border-top: 1px solid rgb(220, 231, 251); padding-top: 14px; font-family: Arial, Helvetica, sans-serif; font-size: 13px; line-height: 2.1; text-size-adjust: 100%;">
                  <a dir="ltr" href="mailto:info@myetijahi.com" style="color: rgb(0, 82, 204); text-decoration: none; font-weight: bold; white-space: nowrap;"><img src="https://erp.etijahcoaching.com/media/Etijahi/etijahi-icon-email.png" width="16" height="16" alt="Email" style="width: 16px; height: 16px; vertical-align: middle; margin: 0px 6px 3px 0px; border: 0px; outline: none; text-decoration: none;">info@myetijahi.com</a>&nbsp;&nbsp;&nbsp;&nbsp;<a dir="ltr" href="https://etijahcoaching.com/" style="color: rgb(0, 82, 204); text-decoration: none; font-weight: bold; white-space: nowrap;"><img src="https://erp.etijahcoaching.com/media/Etijahi/etijahi-icon-website.png" width="16" height="16" alt="Website" style="width: 16px; height: 16px; vertical-align: middle; margin: 0px 6px 3px 0px; border: 0px; outline: none; text-decoration: none;">etijahcoaching.com</a>
                </td>
              </tr></tbody></table>
            </td>
          </tr></tbody></table>
        </td></tr>

        <tr>
          <td bgcolor="#00C9A7" style="background: rgb(0, 201, 167); padding: 26px 40px; text-size-adjust: 100%;" align="center">
            <p style="margin: 0px 0px 4px; font-family: Arial, Helvetica, sans-serif; font-size: 12px; line-height: 1.6; color: rgb(255, 255, 255); font-weight: bold;">Etijah Coaching &amp; Consulting</p>
            <p style="margin: 0px; font-family: &quot;Segoe UI&quot;, Tahoma, Arial, sans-serif; font-size: 12px; line-height: 1.6; color: rgb(255, 255, 255);">اتجاه للإرشاد والاستشارات</p>
          </td>
        </tr>

      </tbody></table>
    </td>
  </tr>
</tbody></table>

<br><a href="{{unsubscribe_url}}" target="_blank">Click here to unsubscribe</a>',
 '',
 '["first_name", "unsubscribe_url"]'::jsonb
)
on conflict (key) do nothing;
